  specs.push([[k, -3], [k, 3]]);
  specs.push([[-5, k], [5, k]]);
}
specs.forEach(sp => {
  const p = new Polygon({ vertices: [apply(M(0), sp[0][0], sp[0][1]), apply(M(0), sp[1][0], sp[1][1])], color: BLUE });
  p.setStrokeWidth(1.5).setFillOpacity(0);
  tGrid.push(p);
});
