  });
  sq.setVertices([apply(m,0,0), apply(m,1,0), apply(m,1,1), apply(m,0,1)]);
  iVec.setVertices([apply(m,0,0), apply(m,1,0)]);
  jVec.setVertices([apply(m,0,0), apply(m,0,1)]);
  setLabel(t);
}
